#' Get entry from UDG file
#'
#' Returns a specific element of a list of \code{udg} entries.
#'
#' Version 1.0 2026-10-26
#'
#' @param seas_obj A \code{seas} object for a single series generated from the 
#'        \code{seasonal} package \insertCite{seasonal2018}{sautilities}. 
#'        This is a required entry.
#' @param this_key Character scalar; keyword found in UDG output generated by X-13ARIMA-SEATS.
#'        This is a required entry.
#' @param this_index Integer scalar; index of entry in vector to extract. If set to 0 (the default), 
#'        get the last entry. If less than zero, return the entire entry.
#' @param return_numeric Logical scalar; if \code{TRUE}, convert character to numeric object.
#'        Default is \code{TRUE}.
#' @param print_warning Logical scalar; if \code{TRUE}, print warning message for keyword not found.
#'        Default is \code{TRUE}.
#' @return The \code{this_index} element of the array from the UDG entry for \code{this_key}.
#'
#' @author Brian C. Monsell, \email{monsell.brian@@bls.gov} or \email{bcmonsell@@gmail.com}
#'
#' @references
#'  \insertAllCited{}
#'
#' @examples 
#' air_seas_short <- 
#'    seasonal::seas(AirPassengers, 
#'                   series.span = ',1960.9', 
#'                   transform.function = "log", 
#'                   arima.model="(0 1 1)(0 1 1)",
#'                   forecast.maxlead = 36, 
#'                   x11 = "", 
#'                   slidingspans = "")
#' fcst_tstat <- 
#'     get_udg_entry(air_seas_short, 'forctval01')
#' @importFrom Rdpack reprompt
#' @export
get_udg_entry <- 
   function(seas_obj = NULL, 
            this_key = NULL, 
            this_index = 0, 
            return_numeric = TRUE,
			print_warning = TRUE) {
    # Author: Brian C. Monsell (OEUS) Version 1.0 2026-10-26
    
    # check if a value is specified for \code{seas_obj}
    if (is.null(seas_obj)) {
        stop("Must specify a seas object")
    } else {
    # check if a seas object is specified for \code{seas_obj}
        if (!inherits(seas_obj, "seas")) {
           stop("First argument must be a seas object")
        }
    }
	
	if (is.null(this_key)) {
        stop("Must specify a key to extract")
    }

    # extract output associated with UDG keyword if UDG keyword not found, 
    # print out error message and set \code{this_udg_string} to \code{NULL}.
	if (print_warning) {
		this_udg_string <- tryCatch(seasonal::udg(seas_obj, this_key), error = function(e) {
			print(paste("this keyword not found: ", this_key, sep = ""))
			NULL
		})
	} else {
		this_udg_string <- tryCatch(seasonal::udg(seas_obj, this_key), error = function(e) {
			NULL
		})
	}
    
    # if \code{this_udg_string} is \code{NULL}, return \code{NULL}
    if (is.null(this_udg_string)) {
        return(this_udg_string)
    }
    
    # if \code{this_udg_string} is fully numeric, return proper element in \code{this_udg_string}
    if (is.numeric(this_udg_string)) {
        # If \code{this_index} is not set by user, set to be the last element in the array
        if (this_index == 0) {
            this_index <- length(this_udg_string)
        }
        return(this_udg_string[this_index])
    }
    
    # if \code{this_udg_string} is an array, create a single string separated by spaces
    if (is.array(this_udg_string)) {
        this_udg_string <- paste(this_udg_string, collapse = " ")
    }
	
	if (this_index < 0) {
		if (return_numeric) {
			return(as.numeric(this_udg_string))
		} else {
			return(this_udg_string)
		}
	}
    
    # Recreate a character array by splitting the string by spaces
    this_vec <- unlist(strsplit(this_udg_string, split = " "))
    
    # If \code{this_index} is not set by user, set to be the last element in the array
    if (this_index == 0) {
        this_index <- length(this_vec)
    }
    
    # If \code{return_numeric} is \code{TRUE}, return output as a number. 
    # If not, return as a character string
    if (return_numeric) {
        return(as.numeric(this_vec[this_index]))
    } else {
        return(this_vec[this_index])
    }
}
